def combos():
    b=''
    rows=['Each instance of A is related to a minimum of zero and a maximum of one instance of B','Each instance of B is related to a minimum of one and a maximum of one instance of A','Each instance of A is related to a minimum of one and a maximum of many instances of B','Each instance of B is related to a minimum of zero and a maximum of many instances of B']
    mk=['zo','oo','om','zm']
    for k,(t,m) in enumerate(zip(rows,mk)):
        y=15+k*60
        b+=bx(10,y,40,38,'A',14)+bx(165,y,40,38,'B',14)+ln(50,y+19,165,y+19)
        if m=='zo': b+=f'<circle cx="150" cy="{y+19}" r="5" fill="#fff" stroke="#111"/><line x1="158" y1="{y+10}" x2="158" y2="{y+28}" stroke="#111" stroke-width="1.5"/>'
        elif m=='oo': b+=f'<line x1="62" y1="{y+10}" x2="62" y2="{y+28}" stroke="#111" stroke-width="1.5"/><line x1="68" y1="{y+10}" x2="68" y2="{y+28}" stroke="#111" stroke-width="1.5"/>'
        elif m=='om': b+=f'<polyline points="160,{y+9} 150,{y+19} 160,{y+29}" fill="none" stroke="#111" stroke-width="1.5"/><line x1="146" y1="{y+10}" x2="146" y2="{y+28}" stroke="#111" stroke-width="1.5"/>'
        else: b+=f'<polyline points="60,{y+9} 70,{y+19} 60,{y+29}" fill="none" stroke="#111" stroke-width="1.5"/><circle cx="78" cy="{y+19}" r="5" fill="#fff" stroke="#111"/>'
        ws=t.split(' ');line1=' '.join(ws[:8]);line2=' '.join(ws[8:])
        b+=T(215,y+15,line1,9,'start',700)+T(215,y+29,line2,9,'start',700)
    return svg(520,260,'Four cardinality and modality combinations between entities A and B',b)
